import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJFGRv8Z.js";var i=JSON.parse(`{"title":"用户与邮箱管理","description":"","frontmatter":{},"headers":[],"relativePath":"admin/users-mailboxes.md","filePath":"admin/users-mailboxes.md","lastUpdated":1788621106000}`),a={name:`admin/users-mailboxes.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="用户与邮箱管理" tabindex="-1">用户与邮箱管理 <a class="header-anchor" href="#用户与邮箱管理" aria-label="Permalink to “用户与邮箱管理”">​</a></h1><h2 id="用户列表与筛选" tabindex="-1">用户列表与筛选 <a class="header-anchor" href="#用户列表与筛选" aria-label="Permalink to “用户列表与筛选”">​</a></h2><p>用户页可按用户名或找回邮箱搜索，按启用状态和管理员角色筛选，并按注册时间、用户名、邮箱或系统配额等级排序。每页可显示 20、50 或 100 条。</p><p>列表中的徽章分别表示：</p><table tabindex="0"><thead><tr><th>徽章</th><th>数据含义</th></tr></thead><tbody><tr><td>普通账号 / NodeLoc 账号 / Google 账号等</td><td>首次注册来源</td></tr><tr><td>青铜、白银、黄金、钻石或王者会员</td><td>NodeLoc 绑定返回的真实 <code>TL0</code>–<code>TL4</code></td></tr><tr><td>系统配额 <code>L0</code>–<code>L4</code></td><td>本站实际使用的配额模板档位</td></tr><tr><td>⚡ 数字</td><td>当前能量余额</td></tr></tbody></table><p>每一行都从该账号自己的 <code>oauth_account_bindings.external_level_code</code> 读取 NodeLoc 等级，只有真实值为 <code>TL2</code> 才显示“黄金会员（TL2）”。普通账号绑定 NodeLoc 后仍显示“普通账号”，同时多一枚真实 NodeLoc 等级徽章。若绑定存在但暂时没有可信等级数据，显示“等级待同步”，不会回退到 <code>users.level</code> 或拿系统配额等级猜测。</p><h2 id="账号控制" tabindex="-1">账号控制 <a class="header-anchor" href="#账号控制" aria-label="Permalink to “账号控制”">​</a></h2><p>展开用户后可执行：</p><ul><li>启用或禁用账号。</li><li>授予或撤销管理员权限。</li><li>查看注册来源、NodeLoc 实际等级与系统配额等级。</li><li>调整 <code>L0</code>–<code>L4</code> 系统配额档位。</li><li>设置存储、邮箱数和每日发信的单用户覆盖值。</li><li>查看邮箱、存储、今日发信、能量钱包、充值与最近流水。</li><li>为本地账号重置密码。</li><li>重置 TOTP、强制下线、代入登录或永久删除。</li></ul><p>OAuth 注册账号的密码由原提供方管理，后台不会显示本地重置入口。管理员重置密码、重置 2FA 和强制下线都会撤销用户现有令牌。</p><p>代入登录时会保留管理员审计身份，并禁止所有凭据变更。结束排障后立即退出代入会话。</p><h2 id="配额优先级" tabindex="-1">配额优先级 <a class="header-anchor" href="#配额优先级" aria-label="Permalink to “配额优先级”">​</a></h2><p>排查用户配额时按以下顺序：</p><ol><li>管理员为该用户设置的覆盖值。</li><li>个人 Pro 套餐提供的权益。</li><li>当前系统配额 <code>L0</code>–<code>L4</code> 的模板值。</li><li>全局默认配额。</li></ol><p>NodeLoc 的 TL 等级只负责通过后台映射选择系统 L 档位。企业邮箱使用组织订阅配额，不由个人 NodeLoc 等级直接决定。</p><p>用户详情里的邮箱数量、存储和“今日发信收件人”只统计该用户的个人邮箱。获分配的企业邮箱不会混入个人数字；企业存储和今日共享发信用量应到对应组织页面查看。</p><h2 id="删除用户" tabindex="-1">删除用户 <a class="header-anchor" href="#删除用户" aria-label="Permalink to “删除用户”">​</a></h2><p>禁用账号只停止访问，不删除数据。永久删除前核对邮箱归属、组织所有权和成员关系、共享、转让、订单、订阅、钱包、工单和 API Key。</p><p>删除流程由事务和数据库约束保护。必要审计日志会保留，已删除用户的外键引用置空；不要直接在数据库中逐表删除来绕过检查。</p><h2 id="邮箱管理" tabindex="-1">邮箱管理 <a class="header-anchor" href="#邮箱管理" aria-label="Permalink to “邮箱管理”">​</a></h2><p>管理员邮箱页显示地址、域名、所属用户、状态、容量和时间。可搜索地址或用户名，点击所属用户可跳到已筛选的用户页。</p><p>可调整：</p><ul><li>外部转发地址配置；来信本地保存后会按正常发信策略执行转发，并把结果写入邮件流转。个人邮箱计用户额度并可能消耗能量，企业邮箱计组织共享额度。</li><li>是否接收邮件。</li><li>是否允许 IMAP、POP3 和 SMTP Submission 等协议访问。</li><li>归档状态。</li></ul><p>邮箱转让、共享、清理和应用专用密码由各自业务流程管理。个人清理与“全部粉碎”接口只接受个人邮箱，不会处理企业邮箱。转让完成后，原所有者不再拥有管理权限；共享当前是只读访问，不授予发信、改设置或删除邮箱权限。</p><h2 id="邮件数据访问" tabindex="-1">邮件数据访问 <a class="header-anchor" href="#邮件数据访问" aria-label="Permalink to “邮件数据访问”">​</a></h2><p>管理员排查邮件时遵守最小访问原则。优先使用邮件 ID、时间、投递状态、认证结果和邮件流日志；确有需要时才查看正文或附件。所有下载接口继续执行邮箱所有权、组织管理员或只读共享范围校验。</p>`,26)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};